  def initialize
    @objects = []
  end

  def register(obj)
    return self if @objects.any? { |o| o.object_id == obj.object_id }

    @objects << obj
    self
  end

  def registered?(obj)
    @objects.any? { |o| o.object_id == obj.object_id }
  end

  def size
    @objects.size
  end

  def to_a
    @objects.dup
  end
end
```

